require __DIR__ . '/../../app/bootstrap.php';$d=current_device();$in=json_input();$callId=(int)($in['call_id']??0);$status=trim((string)($in['status']??''));$allowed=['dialing','ringing','answered','completed','failed','rejected','busy','no_answer'];if(!$callId||!in_array($status,$allowed,true))json_response(['ok'=>false,'error'=>'Invalid call update'],422);
$pdo=db();$q=$pdo->prepare('SELECT * FROM calls WHERE id=? AND device_id=?');$q->execute([$callId,$d['id']]);$call=$q->fetch();if(!$call)json_response(['ok'=>false,'error'=>'Call not found'],404);
$ended=in_array($status,['completed','failed','rejected','busy','no_answer'],true);$answered=$status==='answered';$outcome=$in['outcome']??($ended?$status:null);$started=$call['started_at']?:($status==='dialing'?now_utc():null);$answeredAt=$call['answered_at']?:($answered?now_utc():null);$endedAt=$ended?now_utc():null;$duration=null;if($endedAt&&$answeredAt)$duration=max(0,strtotime($endedAt)-strtotime($answeredAt));
$u=$pdo->prepare('UPDATE calls SET status=?,outcome=COALESCE(?,outcome),started_at=COALESCE(?,started_at),answered_at=COALESCE(?,answered_at),ended_at=COALESCE(?,ended_at),duration_seconds=COALESCE(?,duration_seconds),transcript=COALESCE(?,transcript),ai_summary=COALESCE(?,ai_summary),notes=COALESCE(?,notes),action_result=COALESCE(?,action_result) WHERE id=?');$u->execute([$status,$outcome,$started,$answeredAt,$endedAt,$duration,$in['transcript']??null,$in['ai_summary']??null,$in['notes']??null,$in['action_result']??null,$callId]);
if($ended){$contactStatus=in_array($status,['failed','busy','no_answer'],true)?'failed':'completed';$pdo->prepare('UPDATE campaign_contacts SET status=?,last_error=? WHERE id=?')->execute([$contactStatus,$in['error']??null,$call['contact_id']]);$campaign=(int)$call['campaign_id'];$left=$pdo->prepare("SELECT COUNT(*) FROM campaign_contacts WHERE campaign_id=? AND status IN ('pending','dialing')");$left->execute([$campaign]);if((int)$left->fetchColumn()===0)$pdo->prepare("UPDATE campaigns SET status='completed',completed_at=? WHERE id=?")->execute([now_utc(),$campaign]);}
json_response(['ok'=>true]);
